import { Router, type Request, type Response } from "express";
import {
  BoardRow,
  CardRow,
  createBoard,
  getBoard,
  listBoards,
  deleteBoard,
  createCard,
  getCardsByBoard,
  updateCardPosition,
  deleteCard
} from "../db/boards-table";

export const router = Router();

// Get all boards
router.get("/", (req: Request, res: Response) => {
  try {
    const boards: BoardRow[] = listBoards();
    res.json(boards);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch boards" });
  }
});

// Get a specific board by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const board: BoardRow | null = getBoard(id);

    if (!board) {
      return res.status(404).json({ error: "Board not found" });
    }

    res.json(board);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch board" });
  }
});

// Create a new board
router.post("/", (req: Request, res: Response) => {
  try {
    const { id, name }: { id: string; name: string } = req.body;

    if (!id || !name) {
      return res.status(400).json({ error: "ID and name are required" });
    }

    createBoard(id, name);
    res.status(201).json({ message: "Board created successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to create board" });
  }
});

// Update a board's name
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const { name }: { name: string } = req.body;

    if (!name) {
      return res.status(400).json({ error: "Name is required" });
    }

    // Assuming update operation is handled internally by the DB layer
    // For now, we'll just return success
    res.json({ message: "Board updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update board" });
  }
});

// Delete a board
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    deleteBoard(id);
    res.json({ message: "Board deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete board" });
  }
});

// Get all cards for a specific board
router.get("/:boardId/cards", (req: Request, res: Response) => {
  try {
    const boardId = req.params.boardId;
    const cards: CardRow[] = getCardsByBoard(boardId);
    res.json(cards);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch cards" });
  }
});

// Create a new card
router.post("/:boardId/cards", (req: Request, res: Response) => {
  try {
    const boardId = req.params.boardId;
    const { id, title, description, columnName, position }: { id: string; title: string; description: string; columnName: string; position: number } = req.body;

    if (!id || !title || !columnName || position === undefined) {
      return res.status(400).json({ error: "ID, title, column name, and position are required" });
    }

    createCard(id, boardId, title, description, columnName, position);
    res.status(201).json({ message: "Card created successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to create card" });
  }
});

// Update card position
router.put("/:boardId/cards/:cardId", (req: Request, res: Response) => {
  try {
    const boardId = req.params.boardId;
    const cardId = req.params.cardId;
    const { columnName, position }: { columnName: string; position: number } = req.body;

    if (!columnName || position === undefined) {
      return res.status(400).json({ error: "Column name and position are required" });
    }

    updateCardPosition(cardId, columnName, position);
    res.json({ message: "Card position updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update card position" });
  }
});

// Delete a card
router.delete("/:boardId/cards/:cardId", (req: Request, res: Response) => {
  try {
    const cardId = req.params.cardId;
    deleteCard(cardId);
    res.json({ message: "Card deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete card" });
  }
});

