  getProductById,
  insertProduct,
  updateProductStock
} from "../db/products-table";

export const router = Router();

// GET /catalog/products - Get all products
router.get("/products", (req: Request, res: Response) => {
  try {
    const products: Product[] = getAllProducts();
    res.json(products);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch products" });
  }
});

// GET /catalog/products/:id - Get a specific product by ID
router.get("/products/:id", (req: Request, res: Response) => {
  try {
    const id: number = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid product ID" });
    }

    const product: Product | undefined = getProductById(id);
    if (!product) {
      return res.status(404).json({ error: "Product not found" });
    }

    res.json(product);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch product" });
  }
});

// POST /catalog/products - Create a new product (admin only)
router.post("/products", (req: Request, res: Response) => {
  try {
    const { name, price, stockCount }: { name: string; price: number; stockCount: number } = req.body;

    if (!name || price === undefined || stockCount === undefined) {
      return res.status(400).json({ error: "Name, price, and stockCount are required" });
    }

    insertProduct(name, price, stockCount);
    const createdProduct: Product = getProductById(Number(LastInsertRowId()));

    res.status(201).json(createdProduct);
  } catch (error) {
    res.status(500).json({ error: "Failed to create product" });
  }
});

// PUT /catalog/products/:id - Update product stock (admin only)
router.put("/products/:id", (req: Request, res: Response) => {
  try {
    const id: number = Number(req.params.id);
    const { stockCount }: { stockCount: number } = req.body;

    if (isNaN(id) || stockCount === undefined) {
      return res.status(400).json({ error: "Invalid product ID or stockCount" });
    }

    const existingProduct: Product | undefined = getProductById(id);
    if (!existingProduct) {
      return res.status(404).json({ error: "Product not found" });
    }

    updateProductStock(id, stockCount);
    const updatedProduct: Product = getProductById(id);

    res.json(updatedProduct);
  } catch (error) {
    res.status(500).json({ error: "Failed to update product" });
  }
});

