import { Router, type Request, type Response } from "express";
import { db as productsDb, getAllProducts, getProductById, updateProductStock } from "../db/products-table";
import { db as ordersDb, getAllOrders, getOrderById, insertOrder } from "../db/orders-table";

export const router = Router();

// Create a new order from a cart
router.post("/create", (req: Request, res: Response) => {
  const { customerId, lineItems, paymentStatus } = req.body;

  // Validate input
  if (!customerId || !lineItems || !paymentStatus) {
    return res.status(400).json({ error: "Missing required fields: customerId, lineItems, paymentStatus" });
  }

  // Parse line items
  let parsedLineItems;
  try {
    parsedLineItems = JSON.parse(lineItems);
  } catch {
    return res.status(400).json({ error: "Invalid lineItems format" });
  }

  // Validate line items structure
  if (!Array.isArray(parsedLineItems)) {
    return res.status(400).json({ error: "Line items must be an array" });
  }

  // Check if products exist and have sufficient stock
  const productIds = new Set<number>();
  const updatedStock: Map<number, number> = new Map();

  for (const item of parsedLineItems) {
    const { productId, quantity } = item;

    if (!productId || typeof quantity !== "number" || quantity <= 0) {
      return res.status(400).json({ error: "Invalid product ID or quantity" });
    }

    productIds.add(productId);

    const product = getProductById(productId);
    if (!product) {
      return res.status(400).json({ error: `Product with ID ${productId} not found` });
    }

    if (product.stockCount < quantity) {
      return res.status(400).json({ error: `Not enough stock for product ${productId}` });
    }

    updatedStock.set(productId, product.stockCount - quantity);
  }

  // Update product stocks
  for (const [productId, newStock] of updatedStock.entries()) {
    updateProductStock(productId, newStock);
  }

  // Insert order into database
  const orderId = ordersDb.prepare(
    "INSERT INTO orders (customerId, lineItems, paymentStatus) VALUES (?, ?, ?)"
  ).run(customerId, JSON.stringify(parsedLineItems), paymentStatus).lastInsertRowid;

  // Return created order
  const createdOrder = getOrderById(Number(orderId));
  if (!createdOrder) {
    return res.status(500).json({ error: "Failed to retrieve created order" });
  }

  res.status(201).json(createdOrder);
});

// Get all orders
router.get("/", (req: Request, res: Response) => {
  const orders = getAllOrders();
  res.json(orders);
});

// Get a specific order by ID
router.get("/:orderId", (req: Request, res: Response) => {
  const orderId = Number(req.params.orderId);

  if (isNaN(orderId)) {
    return res.status(400).json({ error: "Invalid order ID" });
  }

  const order = getOrderById(orderId);

  if (!order) {
    return res.status(404).json({ error: "Order not found" });
  }

  res.json(order);
});

