    return res.status(404).json({ error: "Order not found" });
  }

  return res.json({
    orderId,
    customerId: order.customerId,
    lineItems: JSON.parse(order.lineItems),
    paymentStatus: order.paymentStatus
  });
});

// Helper function to update product stock after sale
function updateProductStockAfterSale(productId: number, quantitySold: number): void {
  const product = getProductById(productId);

  if (!product) {
    console.error(`Product with ID ${productId} not found`);
    return;
  }

  const newStock = product.stockCount - quantitySold;
  if (newStock < 0) {
    console.error(`Attempted to sell more than available stock for product ${productId}`);
    return;
  }

  updateProductStock(productId, newStock);
}

// Handle POST /payment/sale
router.post("/sale", (req: Request, res: Response) => {
  const { productId, quantity } = req.body;

  // Validate input
  if (!productId || !quantity) {
    return res.status(400).json({ error: "Missing required fields: productId, quantity" });
  }

  // Check if product exists
  const product = getProductById(Number(productId));
  if (!product) {
    return res.status(404).json({ error: "Product not found" });
  }

  // Check if sufficient stock
  if (product.stockCount < quantity) {
    return res.status(400).json({ error: "Insufficient stock available" });
  }

  // Update product stock
  updateProductStockAfterSale(Number(productId), quantity);

  return res.status(200).json({ message: "Sale processed successfully" });
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to POST, PUT, DELETE requests to /products/
  const isProductWriteRequest = req.method === "POST" || 
                               req.method === "PUT" || 
                               req.method === "DELETE";

  if (!isProductWriteRequest || !req.path.startsWith("/products/")) {
    next();
    return;
  }

  // Check if user has admin role
  const isAdmin = req.headers["x-user-role"] === "admin";

  if (!isAdmin) {
    res.status(403).json({ error: "Admin access required" });
    return;
  }

  next();
}

