import { Router, type Request, type Response } from "express";
import {
  insertReading,
  getReadingsBySensor,
  getLatestReadingByWarehouse
} from "../db/readings-table";
import {
  Device,
  getDeviceById
} from "../db/devices-table";

export const router = Router();

router.post("/sensor-readings", (req: Request, res: Response) => {
  const { sensorId, warehouseId, value, timestamp, apiKey } = req.body;

  // Validate required fields
  if (
    !sensorId ||
    !warehouseId ||
    !value ||
    !timestamp ||
    !apiKey
  ) {
    return res.status(400).json({
      error: "Missing required fields: sensorId, warehouseId, value, timestamp, apiKey"
    });
  }

  // Check if device exists with the provided API key
  const device: Device | undefined = getDeviceById(warehouseId);

  if (!device || device.apiKeyHash !== apiKey) {
    return res.status(401).json({
      error: "Invalid or unauthorized device API key"
    });
  }

  // Insert the reading into the database
  insertReading(
    Number(sensorId),
    Number(warehouseId),
    Number(value),
    Number(timestamp)
  );

  return res.status(201).json({
    message: "Sensor reading recorded successfully",
    data: {
      sensorId,
      warehouseId,
      value,
      timestamp
    }
  });
});

// Get all readings for a specific sensor
router.get("/sensor-readings/:sensorId", (req: Request, res: Response) => {
  const sensorId = Number(req.params.sensorId);

  if (isNaN(sensorId)) {
    return res.status(400).json({
      error: "Invalid sensor ID"
    });
  }

  const readings = getReadingsBySensor(sensorId);

  if (readings.length === 0) {
    return res.status(404).json({
      error: "No readings found for this sensor"
    });
  }

  return res.json(readings);
});

// Get the latest reading for a specific warehouse
router.get("/latest-reading/:warehouseId", (req: Request, res: Response) => {
  const warehouseId = Number(req.params.warehouseId);

  if (isNaN(warehouseId)) {
    return res.status(400).json({
      error: "Invalid warehouse ID"
    });
  }

  const latestReading = getLatestReadingByWarehouse(warehouseId);

  if (!latestReading) {
    return res.status(404).json({
      error: "No readings found for this warehouse"
    });
  }

  return res.json(latestReading);
});

