  min: -10,
  max: 100
};

// Helper function to calculate time difference in milliseconds
function getTimeDifference(currentTime: number, previousTime: number): number {
  return currentTime - previousTime;
}

// Middleware to check device API key
router.use("/alerts", (req: Request, res: Response, next: Function) => {
  // This is a placeholder implementation
  // In a real scenario, we would verify the API key here
  next();
});

// Route to generate alerts
router.get("/alerts", (req: Request, res: Response) => {
  try {
    const currentTime = Date.now();

    // Get all devices
    const devices = getDevicesByWarehouseId(1); // Assuming warehouse ID 1 for now

    const alerts = [];

    for (const device of devices) {
      const latestReading = getLatestReadingByWarehouse(device.warehouseId);

      if (!latestReading) {
        // No reading found, but we still want to check heartbeat
        continue;
      }

      const deviceObj = getDeviceById(device.id);

      if (!deviceObj) {
        continue;
      }

      // Check heartbeat interval
      const timeDiff = getTimeDifference(currentTime, latestReading.timestamp);

      if (timeDiff > HEARTBEAT_INTERVAL_MS) {
        alerts.push({
          deviceId: device.id,
          message: `No heartbeat detected for device ${device.id}`,
          severity: "warning"
        });
      }

      // Check value range
      if (latestReading.value < VALUE_RANGE.min || latestReading.value > VALUE_RANGE.max) {
        alerts.push({
          deviceId: device.id,
          message: `Out-of-range value detected for device ${device.id}: ${latestReading.value}`,
          severity: "critical"
        });
      }
    }

    return res.json({ alerts });
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

