  const userId = Number(req.params.userId);
  const { exercise, sets, reps } = req.body;

  if (isNaN(userId) || !exercise || sets === undefined || reps === undefined) {
    return res.status(400).json({ error: "Invalid input data" });
  }

  try {
    insertWorkout(userId, exercise, sets, reps);
    return res.status(201).json({ message: "Workout created successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to create workout" });
  }
});

// Get feed of workouts from followed users
router.get("/feed/:userId", (req: Request, res: Response) => {
  const userId = Number(req.params.userId);

  if (isNaN(userId)) {
    return res.status(400).json({ error: "Invalid user ID" });
  }

  try {
    // Get followers of the user
    const followers: Follow[] = getFollowers(userId);
    const followerIds = followers.map(follow => follow.follower_id);

    // Get workouts from followed users
    let feedWorkouts: Workout[] = [];

    for (const followerId of followerIds) {
      const workouts: Workout[] = getWorkoutsByUserId(followerId);
      feedWorkouts = [...feedWorkouts, ...workouts];
    }

    return res.json(feedWorkouts);
  } catch (error) {
    return res.status(500).json({ error: "Failed to generate feed" });
  }
});

