import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply to device-related routes
  const isDeviceRoute = req.path.startsWith('/devices/') && 
                       (req.method === 'POST' || 
                        req.method === 'PUT' || 
                        req.method === 'DELETE');

  if (!isDeviceRoute) {
    next();
    return;
  }

  // Check if user is authenticated and is the owner
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  try {
    // For simplicity, we'll assume the token contains owner info
    // In reality, proper JWT verification would be needed
    const [payload] = token.split('.');
    const expectedSignature = createHmac('sha256', secret)
      .update(payload)
      .digest('base64url');

    // This is a simplified version - in practice, you'd want proper JWT handling
    // and possibly a proper library for secure token verification
    const actualSignature = token.split('.')[2];

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(expectedSignature, 'base64url'),
      Buffer.from(actualSignature, 'base64url')
    );

    if (!isValid) {
      res.status(401).json({ error: 'Invalid token' });
      return;
    }

    // In a real implementation, we would extract the owner ID from the token
    // and compare it with the expected owner ID for the device
    // For now, we'll just proceed assuming valid ownership
    next();
  } catch (err) {
    res.status(401).json({ error: 'Authentication failed' });
  }
}

