// Get all cars
router.get("/cars", (req: Request, res: Response) => {
  try {
    const cars: Car[] = getAllCars();
    res.json(cars);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch cars" });
  }
});

// Get a specific car by ID
router.get("/cars/:id", (req: Request, res: Response) => {
  try {
    const id: number = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid car ID" });
    }

    const car: Car | undefined = getCarById(id);
    if (!car) {
      return res.status(404).json({ error: "Car not found" });
    }

    res.json(car);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch car" });
  }
});

// Check car availability for a date range
router.get("/cars/availability", (req: Request, res: Response) => {
  try {
    const startDate: string = req.query.startDate as string;
    const endDate: string = req.query.endDate as string;

    if (!startDate || !endDate) {
      return res.status(400).json({ error: "Start date and end date are required" });
    }

    // In a real implementation, we would filter cars based on availability
    // For now, we'll just return all cars as available
    const cars: Car[] = getAllCars();

    // Filter out cars that have bookings within the specified date range
    const availableCars: Car[] = cars.filter(car => {
      const bookings: Booking[] = getBookingsByCarId(car.id);
      return !bookings.some(booking => 
        booking.startDate <= endDate && booking.endDate >= startDate
      );
    });

    res.json(availableCars);
  } catch (error) {
    res.status(500).json({ error: "Failed to check availability" });
  }
});

// Create a new booking
router.post("/bookings", (req: Request, res: Response) => {
  try {
    const { carId, customerId, startDate, endDate }: { carId: number, customerId: number, startDate: string, endDate: string } = req.body;

    if (!carId || !customerId || !startDate || !endDate) {
      return res.status(400).json({ error: "Car ID, customer ID, start date, and end date are required" });
    }

    // Check if car exists
    const car: Car | undefined = getCarById(carId);
    if (!car) {
      return res.status(404).json({ error: "Car not found" });
    }

    // Check if car is available for the selected dates
    const bookings: Booking[] = getBookingsByCarId(carId);
    const isAvailable: boolean = !bookings.some(booking => 
      booking.startDate <= endDate && booking.endDate >= startDate
    );

    if (!isAvailable) {
      return res.status(409).json({ error: "Car is not available for the selected dates" });
    }

    // Create booking
    insertBooking(carId, customerId, startDate, endDate);

    res.status(201).json({ message: "Booking created successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to create booking" });
  }
});

import { Router, type Request, type Response } from "express";
import { db, getAllBuilds, insertBuild } from "../db/builds-table";

export const router = Router();

// Get current build status per repo
router.get("/status", (req: Request, res: Response) => {
  try {
    // Fetch all builds from the database
    const builds = getAllBuilds();

    // Group builds by repository
    const groupedBuilds: Record<string, any[]> = {};
    builds.forEach(build => {
      if (!groupedBuilds[build.repo]) {
        groupedBuilds[build.repo] = [];
      }
      groupedBuilds[build.repo].push(build);
    });

    // Create response object with repo statuses
    const repoStatuses = Object.keys(groupedBuilds).map(repo => ({
      repo,
      latestStatus: groupedBuilds[repo][0]?.status || "unknown",
      lastUpdated: groupedBuilds[repo][0]?.timestamp || 0
    }));

    res.json({ repos: repoStatuses });
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch build status" });
  }
});

// Ingest build results via webhook
router.post("/webhook", (req: Request, res: Response) => {
  try {
    const { repo, branch, status, timestamp } = req.body;

    // Validate required fields
    if (!repo || !branch || !status || typeof timestamp !== "number") {
      return res.status(400).json({ error: "Missing required fields: repo, branch, status, timestamp" });
    }

    // Insert build result into database
    insertBuild(repo, branch, status, timestamp);

    res.status(201).json({ message: "Build result received successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to process build webhook" });
  }
});

import { Router, type Request, type Response } from "express";
import { db, getAllBuilds, insertBuild } from "../db/builds-table";

export const router = Router();

// Mock Slack client - in a real implementation this would post to Slack
const mockSlackClient = {
  sendMessage: (message: string): void => {
    console.log(`Mock Slack message sent: ${message}`);
  }
};

// Helper to check if a build failed
function hasFailed(build: BuildRow): boolean {
  return build.status === "failed";
}

// Helper to get the most recent build from main branch
function getLatestMainBranchBuild(builds: BuildRow[]): BuildRow | undefined {
  return builds.sort((a, b) => b.timestamp - a.timestamp)
               .find(build => build.branch === "main") ||
               builds[0]; // Fallback to first build if main not found
}

// POST endpoint to notify Slack about failed main branch builds
router.post("/notify", (req: Request, res: Response) => {
  try {
    // Get all builds from the database
    const builds = getAllBuilds();

    // Filter out successful builds and find the latest main branch build
    const latestMainBuild = getLatestMainBranchBuild(builds);

    if (!latestMainBuild || !hasFailed(latestMainBuild)) {
      return res.status(200).json({ message: "No failed main branch builds to notify." });
    }

    // Format the notification message
    const message = `Main branch build failed:
    Repo: ${latestMainBuild.repo}
    Branch: ${latestMainBuild.branch}
    Status: ${latestMainBuild.status}
    Timestamp: ${new Date(latestMainBuild.timestamp).toISOString()}`;

    // Post the message to Slack (mocked in this example)
    mockSlackClient.sendMessage(message);

    // Return success response
    return res.status(200).json({ message: "Notification posted to Slack successfully." });
  } catch (error) {
    return res.status(500).json({ error: "Failed to process notifications." });
  }
});

