import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to POST requests to the check-in endpoint
  if (req.method !== "POST" || !req.path.startsWith("/check-in")) {
    next();
    return;
  }

  // For demonstration purposes, we'll simulate checking membership expiry
  // In a real implementation, this would involve querying a database

  // Simulate getting membership data from request (this is simplified)
  const membershipData = req.body.membership || {};

  // Check if membership has an expiry date
  if (membershipData.expiryDate) {
    const today = new Date().toISOString().split('T')[0];
    const expiryDate = new Date(membershipData.expiryDate).toISOString().split('T')[0];

    // If expiry date is before today, reject the request
    if (expiryDate < today) {
      res.status(403).json({ error: "Membership has expired." });
      return;
    }
  }

  // If we get here, the membership is valid or there was no expiry date
  next();
}

