    const sku = req.params.sku;
    const stockLevel: StockLevel | undefined = getStockLevelBySku(sku);

    if (!stockLevel) {
      return res.status(404).json({ error: "Stock level not found" });
    }

    res.json(stockLevel);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch stock level" });
  }
});

// Log stock movement and recalculate reorder status
router.post("/movement", (req: Request, res: Response) => {
  try {
    const { product_id, quantity, movement_type }: { product_id: number, quantity: number, movement_type: 'in' | 'out' } = req.body;

    if (!(movement_type === 'in' || movement_type === 'out')) {
      return res.status(400).json({ error: "Invalid movement type. Must be 'in' or 'out'" });
    }

    // Log the movement
    logStockMovement(product_id, quantity, movement_type);

    // Update stock level
    let updated = false;

    if (movement_type === 'in') {
      updateStockLevel(`product-${product_id}`, 1, quantity, 10); // Assuming fixed threshold for demonstration
      updated = true;
    } else if (movement_type === 'out') {
      updateStockLevel(`product-${product_id}`, 1, -quantity, 10); // Assuming fixed threshold for demonstration
      updated = true;
    }

    if (!updated) {
      return res.status(500).json({ error: "Failed to update stock level" });
    }

    // Recompute reorder status
    const updatedStockLevel = getStockLevelBySku(`product-${product_id}`);

    if (!updatedStockLevel) {
      return res.status(404).json({ error: "Updated stock level not found" });
    }

    // Check if we need to trigger reorder
    if (updatedStockLevel.currentQuantity <= updatedStockLevel.reorderThreshold) {
      console.log(`Reorder triggered for SKU: product-${product_id}`);
    }

    res.status(201).json(updatedStockLevel);
  } catch (error) {
    res.status(500).json({ error: "Failed to process stock movement" });
  }
});

