import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /expenses/:id/approve and /expenses/:id/reject routes
  const isApproveOrRejectRoute = req.path.match(/^\/expenses\/[^\/]+\/approve$|^\/expenses\/[^\/]+\/reject$/);

  if (!isApproveOrRejectRoute || req.method !== "POST") {
    next();
    return;
  }

  // Check if user has manager role
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  try {
    // Simple token validation (in a real app, you'd decode and verify properly)
    const [payload] = token.split(".");
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const actualSignature = token.split(".")[1];

    if (!actualSignature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(expectedSignature, "base64url"),
      Buffer.from(actualSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // In a real implementation, we would decode the payload to get user info
    // For now, we'll just simulate checking manager status
    const userId = getUserIdFromToken(token);
    const expenseId = req.params[0];

    // Simulate checking if current user is manager of the reportee
    // This is a placeholder - in reality, you'd query your DB
    const isManager = checkIfUserIsManager(userId, expenseId);

    if (!isManager) {
      res.status(403).json({ error: "Forbidden: Manager can only approve/reject their direct reports' expenses." });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
  }
}

function getUserIdFromToken(token: string): string {
  // In a real implementation, this would extract the user ID from the token payload
  // For demo purposes, we'll assume a simple structure
  const payload = token.split(".")[0];
  const decodedPayload = Buffer.from(payload, "base64url").toString("utf8");
  const parsedPayload = JSON.parse(decodedPayload);
  return parsedPayload.userId || "unknown";
}

function checkIfUserIsManager(managerId: string, expenseReporteeId: string): boolean {
  // Placeholder logic - in reality, this should check:
  // 1. Does the authenticated user exist?
  // 2. Is the expense report associated with a direct report?
  // 3. Is the reportee a direct report of the authenticated user?

  // This is a simplified version assuming some predefined relationships
  // In a real system, this would involve querying a database
  return managerId === expenseReporteeId; // Simplified for example purposes
}

