  }
});

// Update a shift
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id: number = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid shift ID" });
    }

    const { description, startTime, endTime, volunteerCapacity }: { description?: string, startTime?: string, endTime?: string, volunteerCapacity?: number } = req.body;

    const existingShift: Shift | undefined = getShiftById(id);
    if (!existingShift) {
      return res.status(404).json({ error: "Shift not found" });
    }

    updateShift(
      id,
      description ?? existingShift.description,
      startTime ?? existingShift.startTime,
      endTime ?? existingShift.endTime,
      volunteerCapacity ?? existingShift.volunteerCapacity
    );

    const updatedShift: Shift = getShiftById(id)!;
    res.json(updatedShift);
  } catch (error) {
    res.status(500).json({ error: "Failed to update shift" });
  }
});

// Delete a shift
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id: number = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid shift ID" });
    }

    const existingShift: Shift | undefined = getShiftById(id);
    if (!existingShift) {
      return res.status(404).json({ error: "Shift not found" });
    }

    deleteShift(id);
    res.json({ message: "Shift deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete shift" });
  }
});

// Sign up a volunteer for a shift
router.post("/:shiftId/signup", (req: Request, res: Response) => {
  try {
    const shiftId: number = Number(req.params.shiftId);
    const { volunteerId }: { volunteerId: number } = req.body;

    if (isNaN(shiftId) || volunteerId === undefined) {
      return res.status(400).json({ error: "Invalid shift ID or volunteer ID" });
    }

    const shift: Shift | undefined = getShiftById(shiftId);
    if (!shift) {
      return res.status(404).json({ error: "Shift not found" });
    }

    const currentSignups: Signup[] = getSignupsByShift(shiftId);
    if (currentSignups.length >= shift.volunteerCapacity) {
      return res.status(400).json({ error: "Shift capacity reached" });
    }

    addSignup(volunteerId, shiftId);
    res.json({ message: "Signup successful" });
  } catch (error) {
    res.status(500).json({ error: "Failed to sign up volunteer" });
  }
});

