  insertReservation
} from "../db/reservations-table";

export const router = Router();

// Get all reservations for a specific date
router.get("/reservations/:date", (req: Request, res: Response) => {
  const date = req.params.date;

  try {
    const reservations = getReservationsByDate(date);
    res.json(reservations);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservations" });
  }
});

// Get a reservation by employee ID and date
router.get("/reservation/:employeeId/:date", (req: Request, res: Response) => {
  const employeeId = Number(req.params.employeeId);
  const date = req.params.date;

  if (isNaN(employeeId)) {
    return res.status(400).json({ error: "Invalid employee ID" });
  }

  try {
    const reservation = getReservationByEmployeeAndDate(employeeId, date);

    if (!reservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    res.json(reservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservation" });
  }
});

